// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(c));
        vm.assume(caddress != address(0));
        // The external calls must succeed for the function to not revert;
        // deploy a helper that always succeeds on the expected selector.
        Helper helper = new Helper();
        address[] memory targets = new address[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            targets[i] = address(helper);
        }
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(C.transfer.selector, from, address(helper), targets, v)
        );
        require(ok, "unexpected revert");
        bytes memory retdata = abi.encodeWithSelector(C.transfer.selector, from, address(helper), targets, v);
        (bool retok, bytes memory result) = address(c).call(retdata);
        require(retok, "unexpected revert on observation call");
        bool ret = abi.decode(result, (bool));
        assertTrue(ret);
    }
}

contract Helper {
    fallback(bytes calldata input) external returns (bytes memory) {
        // Accept any call and return success
        return abi.encode(true);
    }
}

