pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        // Ensure from is an EOA with no code so call to it always succeeds but does nothing in correct version,
        // while in buggy version it calls from instead of caddress, potentially reverting if from has no fallback.
        vm.assume(from.code.length == 0);
        // caddress receives the call in correct version — we allow it to be any address, including EOA (call succeeds).
        // In buggy version, from is called instead, and since from is an EOA, low-level call succeeds.
        // This does not distinguish yet. Need adversarial callee that makes caddress fail.
        // BUT rule says: if difference manifests through behaviour of external party that FAILS or REVERTS,
        // we MUST deploy a helper that embodies the adversarial behaviour.
        // Here the difference is that reference calls caddress, bug calls from.
        // If caddress is a contract that fails, reference reverts; if from is an EOA, bug succeeds => difference.
        // So we need to deploy a failing contract as caddress.
        // We'll deploy it inside test.
        Reverter reverter = new Reverter();
        bool success;
        try c.transfer(from, address(reverter), _tos, v) returns (bool res) {
            success = res;
        } catch {
            success = false;
        }
        // Reference: calls reverter, which reverts -> transfer reverts, success = false.
        // Bug: calls from (EOA), call succeeds -> transfer returns true, success = true.
        // So reference always returns false (revert) for this setup, bug returns true for some inputs.
        // That matches "reference satisfies a general rule, bug breaks it".
        // Rule: transfer must revert when _tos.length>0 and the called address (caddress) is a contract that always reverts.
        // Actually we can assert that success equals false for reference; but reference always reverts, so success is always false.
        // Assert: success == false
        assertTrue(success == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
